-- Reporting only: no publishing mutations.
CREATE TABLE ops_video_facts (
 account_key TEXT NOT NULL,video_id TEXT NOT NULL,published_at INTEGER NOT NULL DEFAULT 0,synced_at INTEGER NOT NULL,
 views REAL,likes REAL,comments REAL,shares REAL,saves REAL,completion REAL,average_watch REAL,retention3 REAL,
 title TEXT NOT NULL DEFAULT '',share TEXT NOT NULL DEFAULT '',PRIMARY KEY(account_key,video_id));
CREATE INDEX ops_video_account_time ON ops_video_facts(account_key,published_at);
CREATE TABLE ops_pilot_batches(batch_id TEXT PRIMARY KEY,pilot_id TEXT NOT NULL,group_id TEXT NOT NULL,group_name TEXT NOT NULL,strategy TEXT NOT NULL);
CREATE TABLE ops_video_owners(account_key TEXT NOT NULL,video_id TEXT NOT NULL,item_id TEXT NOT NULL,PRIMARY KEY(account_key,video_id));
CREATE TABLE ops_task_dirty(item_id TEXT PRIMARY KEY,revision TEXT NOT NULL DEFAULT (lower(hex(randomblob(16)))));
CREATE TABLE ops_report_progress(name TEXT PRIMARY KEY,cursor TEXT NOT NULL DEFAULT '',done INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '');
INSERT INTO ops_report_progress(name) VALUES ('videos'),('tasks'),('pilots'),('legacy');
CREATE INDEX ops_items_job ON psychology_publish_items(job_id);
CREATE INDEX ops_items_schedule ON psychology_publish_items(schedule_at,id);
CREATE TABLE ops_task_facts (
 id TEXT PRIMARY KEY,batch_id TEXT NOT NULL,account_key TEXT NOT NULL,media TEXT NOT NULL,schedule_at INTEGER NOT NULL,published_at INTEGER NOT NULL DEFAULT 0,
 pilot_id TEXT NOT NULL DEFAULT '',group_id TEXT NOT NULL DEFAULT '',group_name TEXT NOT NULL DEFAULT '',strategy TEXT NOT NULL DEFAULT '',
 source TEXT NOT NULL DEFAULT '',variant TEXT NOT NULL DEFAULT '',style TEXT NOT NULL DEFAULT '',rewrite_model TEXT NOT NULL DEFAULT '',copy_hash TEXT NOT NULL DEFAULT '',
 title TEXT NOT NULL DEFAULT '',video_id TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT 'pending',error TEXT NOT NULL DEFAULT '',
 views REAL,likes REAL,comments REAL,shares REAL,saves REAL,completion REAL,average_watch REAL,retention3 REAL,
 synced_at INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0);
CREATE INDEX ops_task_account_schedule ON ops_task_facts(account_key,media,schedule_at);
CREATE INDEX ops_task_account_published ON ops_task_facts(account_key,media,published_at);
CREATE INDEX ops_task_video ON ops_task_facts(account_key,video_id);
CREATE INDEX ops_task_batch ON ops_task_facts(batch_id);
CREATE INDEX ops_task_source ON ops_task_facts(source,schedule_at,id);
CREATE INDEX ops_task_period ON ops_task_facts(media,published_at,views);
CREATE TABLE ops_daily (
 account_key TEXT NOT NULL,media TEXT NOT NULL,day TEXT NOT NULL,basis TEXT NOT NULL,pilot_id TEXT NOT NULL,group_id TEXT NOT NULL,strategy TEXT NOT NULL,variant_kind TEXT NOT NULL,
 planned INTEGER NOT NULL DEFAULT 0,published INTEGER NOT NULL DEFAULT 0,failed INTEGER NOT NULL DEFAULT 0,pending INTEGER NOT NULL DEFAULT 0,stopped INTEGER NOT NULL DEFAULT 0,
 synced INTEGER NOT NULL DEFAULT 0,views REAL NOT NULL DEFAULT 0,potential INTEGER NOT NULL DEFAULT 0,hit INTEGER NOT NULL DEFAULT 0,
 likes REAL NOT NULL DEFAULT 0,likes_n INTEGER NOT NULL DEFAULT 0,comments REAL NOT NULL DEFAULT 0,comments_n INTEGER NOT NULL DEFAULT 0,shares REAL NOT NULL DEFAULT 0,shares_n INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(account_key,media,day,basis,pilot_id,group_id,strategy,variant_kind));
CREATE INDEX ops_daily_period ON ops_daily(media,basis,day,account_key);

CREATE TRIGGER ops_dirty_psychology_publish_items_insert AFTER INSERT ON psychology_publish_items BEGIN INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE id=NEW.id ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_dirty_psychology_publish_items_update AFTER UPDATE OF job_id,receipt_json,execution_status,deleted_at,schedule_at ON psychology_publish_items BEGIN INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE id=NEW.id ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_dirty_psychology_creative_snapshots_insert AFTER INSERT ON psychology_creative_snapshots BEGIN INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE id=NEW.item_id ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_dirty_psychology_creative_snapshots_update AFTER UPDATE OF source_key,variant_id,style_id,copy_hash,copy_json ON psychology_creative_snapshots BEGIN INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE id=NEW.item_id ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_dirty_factory_jobs_insert AFTER INSERT ON factory_jobs BEGIN INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE job_id=NEW.id ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_dirty_factory_jobs_update AFTER UPDATE OF status,error,result_json ON factory_jobs BEGIN INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE job_id=NEW.id ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_dirty_psychology_publish_groups_insert AFTER INSERT ON psychology_publish_groups BEGIN INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE publish_group_id=NEW.id ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_dirty_psychology_publish_groups_update AFTER UPDATE OF status ON psychology_publish_groups BEGIN INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE publish_group_id=NEW.id ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_dirty_factory_publish_records_insert AFTER INSERT ON factory_publish_records BEGIN INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE id=substr(NEW.id,12) ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_dirty_factory_publish_records_update AFTER UPDATE OF value_json ON factory_publish_records BEGIN INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE id=substr(NEW.id,12) ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_pilot_slot_insert AFTER INSERT ON psychology_autopilot_slots WHEN NEW.batch_id<>'' BEGIN INSERT OR IGNORE INTO ops_pilot_batches(batch_id,pilot_id,group_id,group_name,strategy) SELECT trim(j.value),p.id,p.group_id,p.group_name,p.strategy FROM psychology_autopilots p,json_each('['||replace(json_quote(NEW.batch_id),',','","')||']') j WHERE p.id=NEW.autopilot_id AND trim(j.value)<>''; INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE batch_id IN (SELECT trim(value) FROM json_each('['||replace(json_quote(NEW.batch_id),',','","')||']')) ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_pilot_slot_update AFTER UPDATE OF batch_id ON psychology_autopilot_slots WHEN NEW.batch_id<>'' BEGIN INSERT OR IGNORE INTO ops_pilot_batches(batch_id,pilot_id,group_id,group_name,strategy) SELECT trim(j.value),p.id,p.group_id,p.group_name,p.strategy FROM psychology_autopilots p,json_each('['||replace(json_quote(NEW.batch_id),',','","')||']') j WHERE p.id=NEW.autopilot_id AND trim(j.value)<>''; INSERT INTO ops_task_dirty(item_id) SELECT id FROM psychology_publish_items WHERE batch_id IN (SELECT trim(value) FROM json_each('['||replace(json_quote(NEW.batch_id),',','","')||']')) ON CONFLICT(item_id) DO UPDATE SET revision=lower(hex(randomblob(16))); END;

CREATE TRIGGER ops_video_insert AFTER INSERT ON ops_video_facts BEGIN UPDATE ops_task_facts SET published_at=CASE WHEN NEW.published_at>0 THEN NEW.published_at ELSE published_at END,state='published',views=NEW.views,likes=NEW.likes,comments=NEW.comments,shares=NEW.shares,saves=NEW.saves,completion=NEW.completion,average_watch=NEW.average_watch,retention3=NEW.retention3,synced_at=NEW.synced_at WHERE account_key=NEW.account_key AND video_id=NEW.video_id AND id=(SELECT item_id FROM ops_video_owners WHERE account_key=NEW.account_key AND video_id=NEW.video_id); END;

CREATE TRIGGER ops_video_update AFTER UPDATE ON ops_video_facts BEGIN UPDATE ops_task_facts SET published_at=CASE WHEN NEW.published_at>0 THEN NEW.published_at ELSE published_at END,state='published',views=NEW.views,likes=NEW.likes,comments=NEW.comments,shares=NEW.shares,saves=NEW.saves,completion=NEW.completion,average_watch=NEW.average_watch,retention3=NEW.retention3,synced_at=NEW.synced_at WHERE account_key=NEW.account_key AND video_id=NEW.video_id AND id=(SELECT item_id FROM ops_video_owners WHERE account_key=NEW.account_key AND video_id=NEW.video_id); END;

CREATE TRIGGER ops_video_delete AFTER DELETE ON ops_video_facts BEGIN UPDATE ops_task_facts SET views=NULL,likes=NULL,comments=NULL,shares=NULL,saves=NULL,completion=NULL,average_watch=NULL,retention3=NULL,synced_at=0 WHERE account_key=OLD.account_key AND video_id=OLD.video_id; END; CREATE TRIGGER ops_archive_delete AFTER DELETE ON official_report_video_cache BEGIN DELETE FROM ops_video_facts WHERE account_key=OLD.account_key; END;

CREATE TRIGGER ops_fact_insert AFTER INSERT ON ops_task_facts BEGIN INSERT INTO ops_daily(account_key,media,day,basis,pilot_id,group_id,strategy,variant_kind,planned,published,failed,pending,stopped,synced,views,potential,hit,likes,likes_n,comments,comments_n,shares,shares_n) SELECT NEW.account_key,NEW.media,date(NEW.schedule_at/1000,'unixepoch','+8 hours'),'schedule',NEW.pilot_id,NEW.group_id,NEW.strategy,CASE WHEN NEW.variant='' THEN 'original' ELSE 'rewrite' END,1*COALESCE((1),0),1*COALESCE((NEW.state='published'),0),1*COALESCE((NEW.state='failed'),0),1*COALESCE((NEW.state='pending'),0),1*COALESCE((NEW.state='stopped'),0),1*COALESCE((NEW.state='published' AND NEW.views IS NOT NULL),0),1*COALESCE((CASE WHEN NEW.state='published' THEN COALESCE(NEW.views,0) ELSE 0 END),0),1*COALESCE((NEW.state='published' AND NEW.views>=1000),0),1*COALESCE((NEW.state='published' AND NEW.views>=10000),0),1*COALESCE((CASE WHEN NEW.state='published' AND NEW.views IS NOT NULL THEN COALESCE(NEW.likes,0) ELSE 0 END),0),1*COALESCE((NEW.state='published' AND NEW.views IS NOT NULL AND NEW.likes IS NOT NULL),0),1*COALESCE((CASE WHEN NEW.state='published' AND NEW.views IS NOT NULL THEN COALESCE(NEW.comments,0) ELSE 0 END),0),1*COALESCE((NEW.state='published' AND NEW.views IS NOT NULL AND NEW.comments IS NOT NULL),0),1*COALESCE((CASE WHEN NEW.state='published' AND NEW.views IS NOT NULL THEN COALESCE(NEW.shares,0) ELSE 0 END),0),1*COALESCE((NEW.state='published' AND NEW.views IS NOT NULL AND NEW.shares IS NOT NULL),0) WHERE NEW.schedule_at>0 ON CONFLICT(account_key,media,day,basis,pilot_id,group_id,strategy,variant_kind) DO UPDATE SET planned=planned+excluded.planned,published=published+excluded.published,failed=failed+excluded.failed,pending=pending+excluded.pending,stopped=stopped+excluded.stopped,synced=synced+excluded.synced,views=views+excluded.views,potential=potential+excluded.potential,hit=hit+excluded.hit,likes=likes+excluded.likes,likes_n=likes_n+excluded.likes_n,comments=comments+excluded.comments,comments_n=comments_n+excluded.comments_n,shares=shares+excluded.shares,shares_n=shares_n+excluded.shares_n;
INSERT INTO ops_daily(account_key,media,day,basis,pilot_id,group_id,strategy,variant_kind,planned,published,failed,pending,stopped,synced,views,potential,hit,likes,likes_n,comments,comments_n,shares,shares_n) SELECT NEW.account_key,NEW.media,date(NEW.published_at/1000,'unixepoch','+8 hours'),'publish',NEW.pilot_id,NEW.group_id,NEW.strategy,CASE WHEN NEW.variant='' THEN 'original' ELSE 'rewrite' END,1*COALESCE((1),0),1*COALESCE((NEW.state='published'),0),1*COALESCE((NEW.state='failed'),0),1*COALESCE((NEW.state='pending'),0),1*COALESCE((NEW.state='stopped'),0),1*COALESCE((NEW.state='published' AND NEW.views IS NOT NULL),0),1*COALESCE((CASE WHEN NEW.state='published' THEN COALESCE(NEW.views,0) ELSE 0 END),0),1*COALESCE((NEW.state='published' AND NEW.views>=1000),0),1*COALESCE((NEW.state='published' AND NEW.views>=10000),0),1*COALESCE((CASE WHEN NEW.state='published' AND NEW.views IS NOT NULL THEN COALESCE(NEW.likes,0) ELSE 0 END),0),1*COALESCE((NEW.state='published' AND NEW.views IS NOT NULL AND NEW.likes IS NOT NULL),0),1*COALESCE((CASE WHEN NEW.state='published' AND NEW.views IS NOT NULL THEN COALESCE(NEW.comments,0) ELSE 0 END),0),1*COALESCE((NEW.state='published' AND NEW.views IS NOT NULL AND NEW.comments IS NOT NULL),0),1*COALESCE((CASE WHEN NEW.state='published' AND NEW.views IS NOT NULL THEN COALESCE(NEW.shares,0) ELSE 0 END),0),1*COALESCE((NEW.state='published' AND NEW.views IS NOT NULL AND NEW.shares IS NOT NULL),0) WHERE NEW.published_at>0 ON CONFLICT(account_key,media,day,basis,pilot_id,group_id,strategy,variant_kind) DO UPDATE SET planned=planned+excluded.planned,published=published+excluded.published,failed=failed+excluded.failed,pending=pending+excluded.pending,stopped=stopped+excluded.stopped,synced=synced+excluded.synced,views=views+excluded.views,potential=potential+excluded.potential,hit=hit+excluded.hit,likes=likes+excluded.likes,likes_n=likes_n+excluded.likes_n,comments=comments+excluded.comments,comments_n=comments_n+excluded.comments_n,shares=shares+excluded.shares,shares_n=shares_n+excluded.shares_n; END; CREATE TRIGGER ops_fact_update AFTER UPDATE ON ops_task_facts WHEN NEW.account_key IS NOT OLD.account_key OR NEW.media IS NOT OLD.media OR NEW.schedule_at IS NOT OLD.schedule_at OR NEW.published_at IS NOT OLD.published_at OR NEW.pilot_id IS NOT OLD.pilot_id OR NEW.group_id IS NOT OLD.group_id OR NEW.strategy IS NOT OLD.strategy OR NEW.variant IS NOT OLD.variant OR NEW.state IS NOT OLD.state OR NEW.views IS NOT OLD.views OR NEW.likes IS NOT OLD.likes OR NEW.comments IS NOT OLD.comments OR NEW.shares IS NOT OLD.shares BEGIN INSERT INTO ops_daily(account_key,media,day,basis,pilot_id,group_id,strategy,variant_kind,planned,published,failed,pending,stopped,synced,views,potential,hit,likes,likes_n,comments,comments_n,shares,shares_n) SELECT OLD.account_key,OLD.media,date(OLD.schedule_at/1000,'unixepoch','+8 hours'),'schedule',OLD.pilot_id,OLD.group_id,OLD.strategy,CASE WHEN OLD.variant='' THEN 'original' ELSE 'rewrite' END,-1*COALESCE((1),0),-1*COALESCE((OLD.state='published'),0),-1*COALESCE((OLD.state='failed'),0),-1*COALESCE((OLD.state='pending'),0),-1*COALESCE((OLD.state='stopped'),0),-1*COALESCE((OLD.state='published' AND OLD.views IS NOT NULL),0),-1*COALESCE((CASE WHEN OLD.state='published' THEN COALESCE(OLD.views,0) ELSE 0 END),0),-1*COALESCE((OLD.state='published' AND OLD.views>=1000),0),-1*COALESCE((OLD.state='published' AND OLD.views>=10000),0),-1*COALESCE((CASE WHEN OLD.state='published' AND OLD.views IS NOT NULL THEN COALESCE(OLD.likes,0) ELSE 0 END),0),-1*COALESCE((OLD.state='published' AND OLD.views IS NOT NULL AND OLD.likes IS NOT NULL),0),-1*COALESCE((CASE WHEN OLD.state='published' AND OLD.views IS NOT NULL THEN COALESCE(OLD.comments,0) ELSE 0 END),0),-1*COALESCE((OLD.state='published' AND OLD.views IS NOT NULL AND OLD.comments IS NOT NULL),0),-1*COALESCE((CASE WHEN OLD.state='published' AND OLD.views IS NOT NULL THEN COALESCE(OLD.shares,0) ELSE 0 END),0),-1*COALESCE((OLD.state='published' AND OLD